impl Icon {
    #[must_use]
    pub(crate) fn name(self) -> &'static str {
        ICON_NAMES[self as usize]
    }

    #[must_use = "icon resolution result should be used"]
    pub(crate) fn icon(self, style: Style, size: Size) -> Result<IconRef, IconError> {
        let idx = self as usize;
        let entry = &ICON_ENTRIES[idx];
        let available = entry.available;
        if !available.contains(&(style, size)) {
            return Err(IconError::VariantUnavailable {
                pack: PACK_ID,
                name: ::std::borrow::Cow::Borrowed(entry.name),
                requested: (style, size),
                available,
            });
        }
        let variant = match variant_info(style, size) {
            Some(v) => v,
            None => {
                return Err(IconError::VariantUnavailable {
                    pack: PACK_ID,
                    name: ::std::borrow::Cow::Borrowed(entry.name),
                    requested: (style, size),
                    available,
                });
            }
        };
        let codepoint = match entry
            .variants
            .iter()
            .find(|(k, _)| *k == variant.key)
            .map(|(_, cp)| *cp)
        {
            Some(cp) => cp,
            None => {
                return Err(IconError::VariantUnavailable {
                    pack: PACK_ID,
                    name: ::std::borrow::Cow::Borrowed(entry.name),
                    requested: (style, size),
                    available,
                });
            }
        };
        Ok(IconRef {
            family: variant.family,
            codepoint,
        })
    }
}

